script:
const T = BR.THREE, scene = BR.scene, cam = BR.camera;
const R = 170, SPEED = 85, DIST = 95, END = 16, COOLDOWN = 6;
let arm = 0, armLeft = 0, lastSec = 0, cool = 0, blast = null, target = null;

const canvas = document.querySelector('canvas:not(#minimap)');
const flash = document.createElement('div');
flash.style.cssText = 'position:fixed;inset:0;background:#fff;opacity:0;pointer-events:none;z-index:40';
document.body.appendChild(flash);

function mat(color, op) {
  return new T.MeshBasicMaterial({ color, transparent: true, opacity: op, fog: false, depthWrite: false });
}

function sound() {
  try {
    const AC = window.AudioContext || window.webkitAudioContext, ac = new AC();
    const len = ac.sampleRate * 4, buf = ac.createBuffer(1, len, ac.sampleRate), d = buf.getChannelData(0);
    for (let i = 0; i < len; i++) d[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / len, 2.2);
    const src = ac.createBufferSource(); src.buffer = buf;
    const f = ac.createBiquadFilter(); f.type = 'lowpass';
    f.frequency.setValueAtTime(1800, ac.currentTime);
    f.frequency.exponentialRampToValueAtTime(70, ac.currentTime + 3.5);
    const g = ac.createGain(); g.gain.value = 0.9;
    src.connect(f); f.connect(g); g.connect(ac.destination); src.start();
    const o = ac.createOscillator(), og = ac.createGain();
    o.frequency.setValueAtTime(60, ac.currentTime); o.frequency.exponentialRampToValueAtTime(22, ac.currentTime + 3);
    og.gain.setValueAtTime(0.9, ac.currentTime); og.gain.exponentialRampToValueAtTime(0.001, ac.currentTime + 3.5);
    o.connect(og); og.connect(ac.destination); o.start(); o.stop(ac.currentTime + 3.6);
    setTimeout(() => ac.close(), 5000);
  } catch (e) {}
}

function detonate(x, z) {
  const fire = new T.Mesh(new T.SphereGeometry(1, 24, 16), mat(0xfff3c0, 1));
  const ring = new T.Mesh(new T.RingGeometry(0.92, 1, 64).rotateX(-Math.PI / 2), mat(0xffffff, 0.7));
  ring.material.side = T.DoubleSide;
  const stem = new T.Mesh(new T.CylinderGeometry(1, 1.5, 1, 18), mat(0x6b5444, 0.95));
  const cap = new T.Mesh(new T.SphereGeometry(1, 24, 16), mat(0xff8a2a, 0.95));
  const glow = new T.Mesh(new T.SphereGeometry(1, 16, 12), mat(0xffe0a0, 0.8));
  const parts = [fire, ring, stem, cap, glow];
  for (const p of parts) { p.position.set(x, 0, z); p.frustumCulled = false; p.renderOrder = 5; scene.add(p); }
  ring.position.y = 0.6;
  blast = { x, z, t: 0, parts, hit: new Set() };
  cool = COOLDOWN;
  sound();
  const n = (BR.storage.get('count', 0) | 0) + 1; BR.storage.set('count', n);
  BR.toast('Взрыв №' + n);
}

function push(v, dx, dz, d) {
  const k = 1 - d / R, f = 10 + 52 * k, ux = dx / (d || 1), uz = dz / (d || 1);
  v.parked = false;
  v.vx += ux * f; v.vz += uz * f;
  v.vy = 7 + 24 * k; v.air = true;
  v.w = (v.w || 0) + (Math.random() - 0.5) * 9 * k;
  v.vf = v.vx * Math.sin(v.h) + v.vz * Math.cos(v.h);
}

function finish() {
  for (const p of blast.parts) { scene.remove(p); p.geometry.dispose(); p.material.dispose(); }
  blast = null; flash.style.opacity = 0; if (canvas) canvas.style.transform = '';
}

function stepBlast(dt) {
  const b = blast; b.t += dt; const t = b.t;
  const [fire, ring, stem, cap, glow] = b.parts;
  // вспышка и тряска
  flash.style.opacity = Math.pow(Math.max(0, 1 - t / 3), 1.5);
  if (canvas) {
    const a = Math.max(0, 1 - t / 4) * 9;
    canvas.style.transform = a > 0.2 ? 'translate(' + ((Math.random() - 0.5) * a).toFixed(1) + 'px,' + ((Math.random() - 0.5) * a).toFixed(1) + 'px)' : '';
  }
  // огненный шар
  const e = Math.min(1, t / 2.2), s = 4 + 55 * (1 - Math.pow(1 - e, 3));
  fire.scale.setScalar(s); fire.position.y = s * 0.55;
  fire.material.color.lerpColors(new T.Color(0xfff3c0), new T.Color(0xff5a14), Math.min(1, t / 3));
  fire.material.opacity = t < 1.5 ? 1 : Math.max(0, 1 - (t - 1.5) / 3.5);
  glow.scale.setScalar(s * 1.25); glow.position.y = s * 0.55;
  glow.material.opacity = Math.max(0, 0.7 - t * 0.35);
  // ударная волна
  const rr = Math.min(R, SPEED * t);
  ring.scale.setScalar(Math.max(rr, 0.01));
  ring.material.opacity = Math.max(0, 0.7 * (1 - rr / R));
  ring.visible = rr < R;
  // гриб: ножка + шляпа
  const h = 78 * Math.pow(Math.min(1, t / 6), 0.7), rad = 4 + t * 0.7;
  stem.scale.set(rad, Math.max(h, 0.01), rad); stem.position.y = h / 2;
  const cs = Math.min(t, 9), capR = 8 + cs * 4.2, capH = 5 + cs * 1.8;
  cap.scale.set(capR, capH, capR); cap.position.y = h + capH * 0.4;
  cap.material.color.lerpColors(new T.Color(0xff8a2a), new T.Color(0x4a4038), Math.min(1, t / 7));
  const fade = t < 10 ? 1 : Math.max(0, 1 - (t - 10) / 6);
  stem.material.opacity = 0.95 * fade; cap.material.opacity = 0.95 * fade;
  // силовое воздействие: волна толкает машины, когда доходит до них
  if (rr < R + 1) for (const v of BR.vehicles) {
    if (v.remote || b.hit.has(v)) continue;
    const dx = v.x - b.x, dz = v.z - b.z, d = Math.hypot(dx, dz);
    if (d <= rr && d < R) { b.hit.add(v); push(v, dx, dz, d); }
  }
  if (t >= END) finish();
}

function start() {
  if (blast || armLeft > 0 || cool > 0 || BR.state.mode !== 'play') return;
  const dir = new T.Vector3(); cam.getWorldDirection(dir); dir.y = 0;
  if (dir.lengthSq() < 1e-6) dir.set(0, 0, 1); dir.normalize();
  const px = BR.me.inCar ? BR.player.x : BR.me.x, pz = BR.me.inCar ? BR.player.z : BR.me.z;
  target = { x: px + dir.x * DIST, z: pz + dir.z * DIST };
  armLeft = 3; lastSec = 4;
}

BR.on('tick', dt => {
  if (cool > 0) cool -= dt;
  if (armLeft > 0) {
    armLeft -= dt;
    const sec = Math.ceil(Math.max(armLeft, 0));
    if (sec < lastSec && sec > 0) { lastSec = sec; BR.toast('Запуск через ' + sec + '…'); }
    if (armLeft <= 0) { armLeft = 0; detonate(target.x, target.z); }
  }
  if (blast) stepBlast(dt);
});

const chip = BR.ui.addChip('☢ Бомба (N)');
chip.style.pointerEvents = 'auto'; chip.style.cursor = 'pointer';
chip.addEventListener('click', start);
addEventListener('keydown', e => {
  if (e.code === 'KeyN' && !e.repeat && !(e.target && /^(INPUT|TEXTAREA)$/.test(e.target.tagName))) start();
});
